# Initially generated by GitHub Copilot.
"""Generate and write doc/mp-claims.md from explicit claim records."""

from typing import Mapping

from mb_author.claim import ClaimCollection, ClaimRecord
from verify_mp import driver as _driver
from verify_mp import payload_examples

_OUT_PATH = "doc/mp-claims.md"


def _fn_docstring(fn) -> str:
    """Return first paragraph of fn's docstring, collapsed to one line."""
    doc = fn.__doc__ or ""
    first_para = doc.split("\n\n")[0]
    return " ".join(first_para.split())


def _records_by_id(
    claims: ClaimCollection | Mapping[str, ClaimRecord],
) -> Mapping[str, ClaimRecord]:
    if isinstance(claims, ClaimCollection):
        return claims.records_by_id
    return claims


def generate(claims: ClaimCollection | Mapping[str, ClaimRecord]) -> str:
    """Return the full Markdown text for doc/mp-claims.md."""
    records = _records_by_id(claims)
    verifier_registry = _driver.merged_registry()

    lines = [
        "<!-- Initially generated by GitHub Copilot. -->",
        "# MAM-parsed claims index",
        "",
        "Auto-generated by `MAM-basics/py/main_authored.py gen-mp-claims-index`. Do not edit by hand.",
        "",
        "| Claim id | Kind | Subject | Defined in | Verifier | Verifier docstring |",
        "| --- | --- | --- | --- | --- | --- |",
    ]

    for _claim_id, record in sorted(records.items()):
        specific_fn = verifier_registry.get(record.id)
        has_generic_example_verifier = payload_examples.is_example_claim(record)

        verifier_names = []
        verifier_docstrings = []

        if has_generic_example_verifier:
            verifier_names.append("verify_example_payload (generic)")
            verifier_docstrings.append(
                _fn_docstring(payload_examples.verify_example_payload)
            )

        if specific_fn is not None:
            verifier_names.append(specific_fn.__name__)
            verifier_docstrings.append(_fn_docstring(specific_fn))

        if verifier_names:
            fn_name = " + ".join(verifier_names)
            docstring = " + ".join(verifier_docstrings)
        else:
            fn_name = "pending"
            docstring = ""

        # Escape pipe characters in any cell that might contain them.
        def esc(s: str) -> str:
            return s.replace("|", "\\|")

        lines.append(
            f"| {esc(record.id)} "
            f"| {esc(record.kind)} "
            f"| {esc(record.subject)} "
            f"| {esc(record.defined_in)} "
            f"| {esc(fn_name)} "
            f"| {esc(docstring)} |"
        )

    lines.append("")
    return "\n".join(lines)


def write_output(
    claims: ClaimCollection | Mapping[str, ClaimRecord],
    path: str = _OUT_PATH,
) -> str:
    """Write claims index markdown and return output path."""
    text = generate(claims)
    with open(path, "w", encoding="utf-8", newline="") as fh:
        fh.write(text)
    return path
